'use strict';
const names=['Коммуникация','Лидерство','Аналитическое мышление','Креативность','Эмоциональный интеллект','Стратегическое мышление','Работа в команде','Адаптивность','Ответственность','Самоорганизация','Критическое мышление','Инициативность','Обучаемость','Решение проблем','Переговоры','Эмпатия','Управление проектами','Принятие решений','Системное мышление','Внимание к деталям','Настойчивость','Гибкость','Клиентоориентированность','Публичные выступления','Планирование','Управление конфликтами','Цифровая грамотность','Исследование','Предприимчивость','Работа с данными','Управление временем','Надежность','Развитие других'];
const qualities=[['Умение слушать','Способность внимательно воспринимать информацию, понимать собеседника и учитывать его позицию.'],['Убеждение','Способность ясно аргументировать позицию и помогать собеседнику увидеть ее ценность.'],['Ведение переговоров','Способность находить взаимоприемлемые решения и согласовывать интересы.'],['Публичные выступления','Способность уверенно и понятно доносить идеи до аудитории.']];
const custom={1:[['Постановка целей','Умение формулировать понятные цели для команды.'],['Мотивация','Умение поддерживать вовлеченность и инициативу.'],['Делегирование','Умение передавать задачи и ответственность.'],['Обратная связь','Умение помогать другим развиваться через конкретные наблюдения.']],2:[['Анализ информации','Умение выделять значимые факты и закономерности.'],['Логика','Умение выстраивать последовательные рассуждения.'],['Проверка гипотез','Умение проверять предположения на данных.'],['Интерпретация','Умение объяснять смысл полученных результатов.']],3:[['Генерация идей','Умение предлагать новые варианты решения.'],['Воображение','Умение представлять возможные сценарии.'],['Экспериментирование','Готовность пробовать новые подходы.'],['Оригинальность','Умение находить нестандартные решения.']]};
function qs(i){return custom[i]||(i===0?qualities:[['Применение на практике',`Способность применять качество «${names[i].toLowerCase()}» в рабочих задачах.`],['Самостоятельность','Способность действовать без постоянной поддержки и подсказок.'],['Последовательность','Способность проявлять качество регулярно в разных ситуациях.'],['Развитие навыка','Способность замечать зоны роста и осваивать новые подходы.']])}
const fresh=()=>({scores:Array(33).fill(10),areas:Array(33).fill(1/33),edited:Array(33).fill(false),qualities:Array.from({length:33},()=>Array(4).fill(15)),qedited:Array.from({length:33},()=>Array(4).fill(false))});
let state;try{state=JSON.parse(localStorage.getItem('profi.v1'))}catch{}state=state||{scale:30,self:fresh(),profile:{},external:[],fixed:null,id:crypto.randomUUID()};
// Scores are a fixed budget: 330 points, with each cell in [1, 30].
function distribute(weights,total){let out=Array(weights.length).fill(0),active=weights.map((_,i)=>i),rest=total;while(active.length){let sum=active.reduce((v,i)=>v+weights[i],0);let fixed=active.filter(i=>rest*weights[i]/sum<1||rest*weights[i]/sum>30);if(!fixed.length){active.forEach(i=>out[i]=rest*weights[i]/sum);break}fixed.forEach(i=>{out[i]=rest*weights[i]/sum<1?1:30;rest-=out[i]});active=active.filter(i=>!fixed.includes(i))}return out}
function syncScores(d){d.scores=distribute(d.areas,330);d.areas=d.scores.map(v=>v/330)}
if(state.scale!==30){[state.self,state.fixed,...state.external.map(x=>x.data)].filter(Boolean).forEach(d=>{syncScores(d);d.qualities=d.qualities.map(q=>q.map(v=>Math.min(30,v*3)))});state.scale=30;localStorage.setItem('profi.v1',JSON.stringify(state))}
let shared=null,shareError=false;const snapshotParam=new URLSearchParams(location.hash.slice(1)).get('result');
if(snapshotParam){try{let p=JSON.parse(atob(snapshotParam));const nums=(a,n)=>Array.isArray(a)&&a.length===n&&a.every(v=>Number.isFinite(v)&&v>=1&&v<=30);if(!nums(p.s,33)||!Array.isArray(p.q)||p.q.length!==33||!p.q.every(q=>nums(q,4))||!Array.isArray(p.e)||p.e.length!==33||!Array.isArray(p.z)||p.z.length!==33||!p.z.every(q=>Array.isArray(q)&&q.length===4)||Math.abs(p.s.reduce((a,b)=>a+b,0)-330)>.01)throw Error('invalid');shared={scores:p.s,areas:p.s.map(v=>v/330),edited:p.e.map(Boolean),qualities:p.q,qedited:p.z.map(q=>q.map(Boolean))}}catch{shareError=true}}
const fmt=v=>Number(v).toLocaleString('ru-RU',{maximumFractionDigits:1});
let page='map',selected=0,method='manual',resultTab='self',rating=new URLSearchParams(location.hash.slice(1)).get('evaluate'),guest=fresh(),guestDone=false,polygons=[],drag=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>rating?guest:state.self;function save(){try{localStorage.setItem('profi.v1',JSON.stringify(state))}catch{toast('Не удалось сохранить: хранилище браузера заполнено.')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
const steps=(v,minus,plus)=>`<div class="stepper"><button aria-label="Уменьшить оценку" onclick="${minus}">−</button><div><strong>${fmt(v)}</strong><small> / 30</small></div><button aria-label="Увеличить оценку" onclick="${plus}">+</button></div>`;
function intro(tag,title,sub){return `<div class="eyebrow">${tag}</div><div class="intro"><div><h1>${title}</h1><p>${sub}</p></div><span class="pill">✳ 33 грани вашей личности</span></div>`}
function render(){if(shared||shareError){sharedPage();return}document.body.classList.toggle('rating-mode',!!rating);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#badge').textContent=state.external.length;$('#crumb').textContent=rating?'Независимая оценка · личные данные скрыты':'Личное пространство / '+({map:'Карта качеств',profile:'Мой профиль',results:'Мои результаты',external:'Взгляд со стороны'}[page]);if(rating&&guestDone){$('#app').innerHTML='<div class="completed panel"><div class="eyebrow">ОЦЕНКА ЗАВЕРШЕНА</div><h1>Спасибо за ваш взгляд</h1><p>Демонстрационная оценка сохранена на этом устройстве. Владелец увидит средний результат, когда ответят два разных человека.</p><p>Это прототип: отправка между устройствами пока не подключена.</p><button class="secondary" onclick="location.hash=\'\';location.reload()">Вернуться в демопрототип</button></div>';return}if(rating||page==='map')mapPage();if(!rating&&page==='profile')profilePage();if(!rating&&page==='results')resultsPage();if(!rating&&page==='external')externalPage()}
function mapPage(){let d=current(),n=d.edited.filter(Boolean).length;$('#app').innerHTML=intro(rating?'ВЗГЛЯД СО СТОРОНЫ':'ВАШ ПРОФЕССИОНАЛЬНЫЙ ПОРТРЕТ',rating?'Как вы видите этого человека?':'У каждого таланта — своя форма',rating?'Оцените качества независимо. Начальная карта нейтральна и не содержит самооценку владельца.':'Исследуйте свои сильные стороны. Соберите карту, которая отражает именно вас.')+`<div class="layout"><section class="panel map-panel"><div class="panel-top"><strong>Карта профессиональных качеств</strong><span>Квадратная карта Вороного</span></div><div class="map-wrap"><svg id="diagram" viewBox="0 0 700 620" role="img" aria-label="Интерактивная диаграмма 33 профессиональных качеств"></svg></div><div class="legend"><span><i class="dot"></i>Еще не оценено (○ — стартовый балл)</span><span><i class="dot on"></i>Ваша оценка</span><span>↗ «Внутрь» — качества кластера</span></div><div class="map-foot"><span>Ваш прогресс</span><span><b>${n}</b> из 33 кластеров</span></div><div class="progress"><div style="width:${n/33*100}%"></div></div></section><section><div class="panel" id="cluster"></div><div class="hint" style="margin-top:15px"><b>Как устроена карта?</b>Выберите область и задайте оценку от 1 до 30. Ее площадь изменится, а остальные пропорционально подстроятся. Цифры всех кластеров меняются пропорционально их площади. Общая сумма — 330 баллов; пределы каждого — 1–30.</div></section></div><div class="bottom-bar"><p>↺ Вы можете вернуться к редактированию в любой момент.<br>Названия качеств — пример для демонстрации.</p><button class="primary" onclick="fix()">Зафиксировать результат &nbsp; →</button></div>`;draw(d);clusterPanel()}
function clusterPanel(){let d=current(),i=selected;$('#cluster').innerHTML=`<div class="category">КЛАСТЕР ${String(i+1).padStart(2,'0')} / 33</div><div class="cluster-title">${names[i]}</div><p class="description">${i===0?'Умение выстраивать диалог, делиться идеями и находить общий язык с разными людьми.':`Способность проявлять ${names[i].toLowerCase()} в профессиональной деятельности и повседневных рабочих ситуациях.`}</p><span class="status">${d.edited[i]?'● Вы оценили этот кластер':'○ Пока не оценено'}</span><label>Насколько это про вас?</label><div style="margin-top:12px">${steps(d.scores[i],'adjust(-1)','adjust(1)')}</div><div class="scale"><span>Выражено слабо</span><span>Выражено сильно</span></div><button class="secondary wide detail-btn" onclick="details(${i})">Исследовать качества &nbsp; ↗</button><div class="divider"></div><div class="panel-top"><span>Доля на карте</span><strong>${(d.areas[i]*100).toFixed(1)}%</strong></div><p style="font-size:10px;margin-bottom:0">Внутри — 4 качества с определениями.<br>Нажмите, чтобы оценить каждое отдельно.</p>`}
function adjust(delta,value){let d=current(),i=selected,v=Math.max(1,Math.min(30,value??d.scores[i]+delta));if(v===d.scores[i]&&d.edited[i])return;let indices=d.scores.map((_,j)=>j).filter(j=>j!==i),other=distribute(indices.map(j=>d.scores[j]),330-v);d.scores[i]=v;indices.forEach((j,k)=>d.scores[j]=other[k]);d.areas=d.scores.map(v=>v/330);d.edited[i]=true;if(!rating)save();mapPage()}
// Capacity-constrained power diagram: clipping each cell by all pairwise power bisectors.
const seeds=Array.from({length:33},(_,i)=>{let a=i*2.39996323,r=45+235*Math.sqrt(i/32);return [350+Math.cos(a)*r,310+Math.sin(a)*r]});
const outer=[[60,20],[640,20],[640,600],[60,600]];
function clip(poly,a,b,c){let out=[];for(let k=0;k<poly.length;k++){let p=poly[k],q=poly[(k+1)%poly.length],f=a*p[0]+b*p[1]-c,g=a*q[0]+b*q[1]-c;if(f<=0)out.push(p);if((f<0&&g>0)||(f>0&&g<0)){let t=f/(f-g);out.push([p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1])])}}return out}
function area(p){let s=0;for(let i=0;i<p.length;i++){let q=p[(i+1)%p.length];s+=p[i][0]*q[1]-q[0]*p[i][1]}return Math.abs(s/2)}
function cells(w){return seeds.map((p,i)=>{let poly=outer;for(let j=0;j<33&&poly.length;j++){if(i===j)continue;let q=seeds[j];poly=clip(poly,2*(q[0]-p[0]),2*(q[1]-p[1]),q[0]**2+q[1]**2-p[0]**2-p[1]**2+w[i]-w[j])}return poly})}
function geometry(areas){let w=Array(33).fill(0),total=area(outer),p;for(let k=0;k<1800;k++){p=cells(w);let error=0;for(let i=0;i<33;i++){let diff=total*areas[i]-area(p[i]);error=Math.max(error,Math.abs(diff)/total);w[i]+=diff*.12}if(error<.00015)break}return cells(w)}
function centroid(p){let a=0,x=0,y=0;for(let i=0;i<p.length;i++){let q=p[(i+1)%p.length],c=p[i][0]*q[1]-q[0]*p[i][1];a+=c;x+=(p[i][0]+q[0])*c;y+=(p[i][1]+q[1])*c}return [x/(3*a),y/(3*a)]}
function draw(d,selector='#diagram',interactive=true){const svg=$(selector);if(!svg)return;polygons=geometry(d.areas);svg.innerHTML=polygons.map((p,i)=>{if(!p.length)return '';let [x,y]=centroid(p),words=names[i].split(' '),fill=d.edited[i]?['#94b59a','#a2bda0','#82aa93','#b0c7a4'][i%4]:['#e2e8dc','#dce5d5','#e9ecdf','#d6e1d0','#e4e9dc'][i%5];return `<g><path data-i="${i}" tabindex="${interactive?0:-1}" role="button" aria-label="${names[i]}, ${d.edited[i]?d.scores[i]+' из 30':'не оценено'}" d="M${p.map(v=>v.join(',')).join('L')}Z" fill="${fill}" class="${interactive&&i===selected?'selected':''}"></path><text x="${x}" y="${y-(words.length-1)*6}" class="${i===selected?'selected-text':''}">${words.map((s,k)=>`<tspan x="${x}" dy="${k?12:0}">${s}</tspan>`).join('')}<tspan class="cell-score" x="${x}" dy="19">${fmt(d.scores[i])} / 30${d.edited[i]?'':' · ○'}</tspan></text><text class="cell-enter" data-detail="${i}" x="${x}" y="${y+(words.length-1)*6+36}" role="button" tabindex="0" aria-label="Открыть качества: ${names[i]}">Внутрь ↗</text></g>`}).join('');svg.querySelectorAll('[data-detail]').forEach(el=>{const open=()=>{let i=+el.dataset.detail;if(interactive){selected=i;clusterPanel()}details(i,!interactive,d)};el.onclick=e=>{e.stopPropagation();open()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});if(interactive){svg.querySelectorAll('path').forEach(el=>{el.onclick=()=>{if(drag?.moved)return;selected=+el.dataset.i;mapPage()};el.ondblclick=()=>details(+el.dataset.i);el.onkeydown=e=>{if(e.key==='Enter'){selected=+el.dataset.i;mapPage()}};el.onpointerdown=e=>{if(+el.dataset.i!==selected)return;drag={y:e.clientY,value:d.scores[selected],moved:false};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!drag)return;if(Math.abs(e.clientY-drag.y)>12)drag.moved=true};el.onpointerup=e=>{if(!drag)return;let dr=drag;drag=null;if(dr.moved){adjust(0,Math.round(dr.value+(dr.y-e.clientY)/20))}}})}}
function details(i,readonly=false,d=null){let data=d||current();$('#modal').hidden=false;$('#modal').innerHTML=`<div class="dialog"><div class="dialog-head"><div class="category">КАРТА КАЧЕСТВ / ВНУТРИ КЛАСТЕРА</div><button onclick="closeModal()" aria-label="Закрыть">×</button></div><h1 style="font-size:28px">${names[i]}</h1><p style="font-size:12px">${readonly?'Оценки вложенных качеств.':'Оцените каждое качество. Изменения сохраняются при возвращении к карте.'}</p>${qs(i).map(([name,desc],j)=>`<div class="quality"><h3>${name}</h3><p>${desc}</p>${readonly?`<b>${data.qedited[i][j]?Number(data.qualities[i][j]).toFixed(1)+' / 30':'Не оценено'}</b>`:steps(data.qualities[i][j],`qadjust(${i},${j},-1)`,`qadjust(${i},${j},1)`)}<small>${data.qedited[i][j]?'Оценено':'Еще не оценено'}</small></div>`).join('')}<button class="primary wide" onclick="closeModal()">Вернуться ${readonly?'к результатам':'к карте'}</button></div>`}
function qadjust(i,j,v){let d=current();d.qualities[i][j]=Math.max(1,Math.min(30,d.qualities[i][j]+v));d.qedited[i][j]=true;if(!rating)save();details(i)}function closeModal(){$('#modal').hidden=true}
function fix(){let d=current();if(!d.edited.some(Boolean)&&!d.qedited.flat().some(Boolean)){toast('Сначала оцените хотя бы одно качество');return}if(rating){$('#modal').hidden=false;$('#modal').innerHTML='<form class="dialog" id="guest-form"><div class="dialog-head"><h2>Представьтесь</h2><button type="button" onclick="closeModal()">×</button></div><p>Ваше имя появится в списке оценщиков. Результаты откроются владельцу после двух разных участников.</p><label>Имя<input name="first" required maxlength="60" autocomplete="given-name"></label><label style="margin-top:15px">Фамилия<input name="last" required maxlength="60" autocomplete="family-name"></label><p style="font-size:11px">Демоверсия: оценка сохранится только в этом браузере.</p><button class="primary wide">Зафиксировать оценку</button></form>';$('#guest-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),name=(f.get('first').trim()+' '+f.get('last').trim()).replace(/\s+/g,' ');if(name.length<3)return;let key=name.toLocaleLowerCase('ru');if(state.external.some(x=>x.key===key)){toast('Этот человек уже оставил оценку на устройстве');return}state.external.push({name,key,data:structuredClone(guest),profile:rating});save();guestDone=true;closeModal();render()};return}state.fixed=structuredClone(d);state.fixedAt=new Date().toISOString();save();page='results';render();toast('Результат зафиксирован')}
function ranking(d){return d.areas.map((a,i)=>({a,i})).sort((a,b)=>b.a-a.a).map(({a,i},k)=>`<div class="rank"><span style="color:#9ca695">${String(k+1).padStart(2,'0')}</span><div><button onclick="showResultDetail(${i})">${names[i]} ↗</button><div class="bar"><i style="width:${a/Math.max(...d.areas)*100}%"></i></div><small>${d.edited[i]?'Оценено':'Не редактировалось напрямую'}</small></div><strong>${(a*100).toFixed(1)}%<small>${fmt(d.scores[i])+'/30'}</small></strong></div>`).join('')}
function resultsPage(){if(!state.fixed){$('#app').innerHTML=intro('ВАШ ПРОФИЛЬ','Результат еще впереди','Сначала сформируйте карту и зафиксируйте свою оценку.')+'<div class="panel empty"><h2>Начните с карты качеств</h2><p>Вы можете оценивать кластеры в любом порядке.</p><button class="primary" onclick="go(\'map\')">Перейти к карте →</button></div>';return}let d=state.fixed;$('#app').innerHTML=intro('МОИ РЕЗУЛЬТАТЫ','Ваш профессиональный профиль','Зафиксировано '+new Date(state.fixedAt).toLocaleDateString('ru-RU')+' · Самооценка хранится отдельно от мнения окружающих.')+`<div class="results-grid"><div><section class="panel"><div class="panel-top"><strong>Ваша самооценка</strong><span>${d.edited.filter(Boolean).length} / 33 оценено</span></div><div class="map-wrap"><svg id="result-map" viewBox="0 0 700 620"></svg></div><button class="secondary wide" onclick="go('map')">Продолжить редактирование</button></section><div class="notice">Сохраненный результат остается прежним, пока вы снова не нажмете «Зафиксировать результат».</div><button class="primary" onclick="share()">Поделиться профилем ↗</button></div><section class="panel"><h2>Рейтинг качеств</h2><p style="font-size:11px">Все 33 кластера по убыванию доли на карте. Нажмите на название, чтобы посмотреть вложенные качества.</p>${ranking(d)}</section></div>`;draw(d,'#result-map',false)}
function showResultDetail(i){let d=shared||(page==='external'?average():state.fixed);details(i,true,d)}
function snapshot(d){return btoa(JSON.stringify({s:d.scores,q:d.qualities,e:d.edited,z:d.qedited}))}
function share(){if(!state.fixed){toast('Сначала зафиксируйте самооценку');return}let url=location.origin+location.pathname+'#result='+snapshot(state.fixed);$('#modal').hidden=false;$('#modal').innerHTML=`<div class="dialog"><div class="dialog-head"><h2>Поделиться вашим результатом</h2><button onclick="closeModal()">×</button></div><p>Другой человек увидит вашу зафиксированную карту, баллы из 30, рейтинг и вложенные качества. Анкета, контакты и PDF не передаются.</p><label>Ссылка на результат<input id="share-url" readonly value="${esc(url)}"></label><div class="notice">Ссылка содержит снимок результата и работает на другом устройстве. После изменения карты зафиксируйте результат и создайте новую ссылку.</div><button class="secondary" onclick="copyLink()">Скопировать ссылку</button> <button class="primary" onclick="previewShared()">Посмотреть как получатель →</button></div>`}
function previewShared(){location.hash='result='+snapshot(state.fixed);location.reload()}
function sharedPage(){document.body.classList.add('rating-mode');$('#crumb').textContent='Общий доступ / Профессиональный профиль';$('.save').textContent='Снимок результата · только просмотр';if(!shared){$('#app').innerHTML='<div class="panel empty"><h2>Ссылка повреждена</h2><p>Попросите владельца повторно скопировать полную ссылку.</p></div>';return}$('#app').innerHTML=intro('РЕЗУЛЬТАТ, КОТОРЫМ С ВАМИ ПОДЕЛИЛИСЬ','Профессиональный профиль','Сохраненная карта владельца. Откройте любой кластер, чтобы увидеть вложенные качества.')+`<div class="results-grid"><section class="panel"><h2>Карта качеств</h2><div class="map-wrap"><svg id="shared-map" viewBox="0 0 700 620"></svg></div><div class="notice">Шкала 1–30 · цифры пропорциональны площади.<br>○ — кластер не редактировался напрямую.<br>Это снимок: просмотр не меняет результат владельца.</div></section><section class="panel"><h2>Рейтинг качеств</h2>${ranking(shared)}</section></div>`;draw(shared,'#shared-map',false)}
async function copyLink(){try{await navigator.clipboard.writeText($('#share-url').value);toast('Ссылка скопирована')}catch{$('#share-url').select();toast('Выделенная ссылка готова для копирования')}}function previewGuest(){location.hash='evaluate='+state.id;location.reload()}
function average(){let d=fresh(),all=state.external.filter(x=>x.profile===state.id),count=all.length;if(!count)return d;d.areas=d.areas.map((_,i)=>all.reduce((s,x)=>s+x.data.areas[i],0)/count);for(let i=0;i<33;i++){let evaluated=all.filter(x=>x.data.edited[i]);d.edited[i]=evaluated.length>0;d.scores[i]=evaluated.length?evaluated.reduce((s,x)=>s+x.data.scores[i],0)/evaluated.length:5;for(let j=0;j<4;j++){let q=all.filter(x=>x.data.qedited[i][j]);d.qedited[i][j]=!!q.length;d.qualities[i][j]=q.length?q.reduce((s,x)=>s+x.data.qualities[i][j],0)/q.length:5}}d.scores=d.areas.map(v=>v*330);return d}
function externalPage(){let all=state.external.filter(x=>x.profile===state.id),n=all.length;$('#app').innerHTML=intro('ОБРАТНАЯ СВЯЗЬ','Посмотрите на себя со стороны','Независимые оценки помогают увидеть то, что мы сами не замечаем.')+`<div class="panel"><div class="external-header"><div><h2>${n} ${n===1?'оценка получена':'оценок получено'}</h2><p style="font-size:12px">${n<2?'Результаты откроются после двух разных участников.':'Усредненные данные обновляются с каждым новым участником.'}</p></div><button class="primary" onclick="share()">Пригласить оценщика ↗</button></div>${n<2?`<div class="empty"><div style="font-size:40px;color:#9daf8f">◎</div><h2>${n===1?'Первый взгляд уже получен':'Один профиль. Разные точки зрения.'}</h2><p>${n===1?'Содержание первой оценки скрыто. Пригласите еще одного участника.':'Пригласите коллег или знакомых — их карта начнется с нейтрального состояния.'}</p></div>`:`<div class="people">${all.map(x=>`<span class="person">${esc(x.name)}</span>`).join('')}</div>`}</div><div class="notice">Демонстрационный режим · оценки хранятся на этом устройстве. Доли карты усредняются по всем участникам; баллы пропорциональны долям. Неоцененные вложенные качества исключаются из среднего.</div><button class="secondary" onclick="demoExternal()">Добавить демонстрационную оценку</button>${n>=2?'<div class="results-grid" style="margin-top:22px"><div class="panel"><h2>Внешний профиль</h2><div class="map-wrap"><svg id="external-map" viewBox="0 0 700 620"></svg></div><p style="font-size:11px">Самооценка остается без изменений. Числовые баллы пропорциональны усредненным долям карты.</p></div><div class="panel"><h2>Усредненный рейтинг</h2>'+ranking(average())+'</div></div>':''}`;if(n>=2)draw(average(),'#external-map',false)}
function demoExternal(){let n=state.external.filter(x=>x.profile===state.id).length,d=fresh();d.scores=d.scores.map((_,i)=>2+(i*7+n*3)%9);let sum=d.scores.reduce((a,b)=>a+b,0);d.areas=d.scores.map(x=>x/sum);syncScores(d);d.edited.fill(true);d.qualities=d.qualities.map((q,i)=>q.map((_,j)=>1+(i+j*3+n)%30));d.qedited=d.qedited.map(q=>q.map(()=>true));let name=['Анна Смирнова','Михаил Волков','Елена Кузнецова'][n%3]+' · демо '+(n+1);state.external.push({name,key:'demo-'+crypto.randomUUID(),data:d,profile:state.id});save();render();toast('Добавлена демонстрационная оценка')}
const professions=['Аналитик','Менеджер проектов','Разработчик','Дизайнер','Маркетолог','Предприниматель','Преподаватель','HR-специалист','Инженер','Врач','Юрист','Финансист','Руководитель','Другое'];
function field(label,key,type='text'){return `<label>${label}<input name="${key}" type="${type}" value="${esc(state.profile[key]||'')}" ${key==='email'?'autocomplete="email"':''}></label>`}
function selectField(label,key,values,multi=false){return `<label>${label}<select name="${key}" ${multi?'multiple size="4"':''}>${multi?'':'<option value="">Выберите из списка</option>'}${values.map(v=>`<option ${multi?(state.profile[key]||[]).includes(v)?'selected':'':state.profile[key]===v?'selected':''}>${v}</option>`).join('')}</select>${multi?'<small>Для выбора нескольких удерживайте Ctrl / ⌘</small>':''}</label>`}
function profilePage(){let p=state.profile;$('#app').innerHTML=intro('ЗНАКОМСТВО','Давайте начнем с вас','Заполните профиль удобным способом. Карту качеств можно исследовать уже сейчас.')+`<div class="tabs"><button class="${method==='manual'?'active':''}" onclick="setMethod('manual')">Заполнить вручную</button><button class="${method==='pdf'?'active':''}" onclick="setMethod('pdf')">Загрузить резюме</button></div><form id="profile-form" class="panel" style="max-width:950px"><div class="form-grid">${field('Имя и фамилия','name')}${field('Электронная почта','email','email')}${field('Телефон','phone','tel')}${method==='manual'?field('Дата рождения','birth','date')+selectField('Страна','country',['Россия','Казахстан','Беларусь','Армения','Грузия','Узбекистан','Другая'])+selectField('Уровень образования','education',['Среднее','Среднее профессиональное','Бакалавриат','Специалитет','Магистратура','Аспирантура']):`<div class="upload full"><h3>Загрузите PDF-резюме</h3><p style="font-size:11px">Файл сохраняется в профиле на этом устройстве. Без автоматического распознавания. До 10 МБ.</p><input id="resume" type="file" accept="application/pdf,.pdf"><div id="resume-status" style="margin-top:12px">${p.resumeName?esc(p.resumeName)+' <button type="button" class="secondary" onclick="openResume()">Открыть PDF ↗</button>':''}</div></div>`}${field('Университет','university')}${field('Специальность','specialty')}${selectField('Текущая профессия','profession',professions)}${selectField('Предыдущие профессии','previous',professions,true)}<label class="full">Удовлетворенность текущей профессией · <b id="sat">${p.satisfaction||5}</b> / 10<input name="satisfaction" type="range" min="1" max="10" value="${p.satisfaction||5}" oninput="document.querySelector('#sat').textContent=this.value"></label><label class="full">Что еще вы хотите рассказать о себе?<textarea name="comment" maxlength="5000">${esc(p.comment||'')}</textarea></label><label class="full check"><input type="checkbox" name="mentor" ${p.mentor?'checked':''}>Хочу быть ментором</label><div class="full bottom-bar"><p>Демоверсия: без аккаунта и регистрации на сервере.<br>Личная анкета не включается в ссылку для оценщиков.</p><button class="primary">Сохранить и перейти к карте →</button></div></div></form>`;$('#profile-form').onsubmit=e=>{e.preventDefault();persistForm();save();go('map');toast('Профиль сохранен')};if($('#resume'))$('#resume').onchange=uploadResume}
function persistForm(){const form=$('#profile-form');if(!form)return;let data=new FormData(form);for(let [k,v] of data)if(k!=='previous')state.profile[k]=v;state.profile.previous=data.getAll('previous');state.profile.mentor=data.has('mentor');state.profile.method=method}
function setMethod(m){persistForm();save();method=m;profilePage()}
function dbOpen(){return new Promise((resolve,reject)=>{let r=indexedDB.open('profi-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function uploadResume(e){let f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){toast('Максимальный размер файла — 10 МБ');e.target.value='';return}let head=await f.slice(0,5).text();if(head!=='%PDF-'){toast('Выберите корректный PDF-файл');e.target.value='';return}try{let db=await dbOpen();await new Promise((res,rej)=>{let t=db.transaction('files','readwrite');t.objectStore('files').put(f,'resume');t.oncomplete=res;t.onerror=rej});state.profile.resumeName=f.name;save();$('#resume-status').innerHTML=esc(f.name)+' <button type="button" class="secondary" onclick="openResume()">Открыть PDF ↗</button>';toast('PDF сохранен в профиле')}catch{toast('Не удалось сохранить файл в браузере')}}
async function openResume(){try{let db=await dbOpen(),f=await new Promise((res,rej)=>{let r=db.transaction('files').objectStore('files').get('resume');r.onsuccess=()=>res(r.result);r.onerror=rej});if(!f){toast('Файл недоступен на этом устройстве');return}let url=URL.createObjectURL(f);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{toast('Не удалось открыть PDF')}}
function go(p){if(page==='profile'){persistForm();save()}page=p;render();window.scrollTo(0,0)}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});method=state.profile.method||'manual';render();
